<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
if(PHP_SAPI!=='cli')header('Cache-Control: no-store, private');
$admin=require_admin($pdo);if(!billing_operations_ready($pdo)){http_response_code(503);exit('Billing Analytics requires the latest database upgrade.');}
$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{
    $op=(string)($_POST['op']??'');$reason=trim((string)($_POST['reason']??''));
    if($op==='settings'){$settings=billing_operations_save_settings($pdo,$admin,$_POST);$success='Billing operations settings updated.';}
    elseif($op==='snapshot'){$snap=billing_operations_snapshot_day($pdo);$success='Billing snapshot rebuilt for '.(string)$snap['snapshot_date'].'.';}
    elseif($op==='run_dunning'){$r=billing_operations_process_due_dunning($pdo,$admin);billing_operations_snapshot_day($pdo);$success='Dunning review complete: '.$r['reviewed'].' reviewed, '.$r['suspended'].' suspended, '.$r['grace'].' retained in grace.';}
    elseif($op==='grant_grace'){billing_operations_grant_grace($pdo,$admin,(string)($_POST['case_id']??''),(int)($_POST['days']??7),$reason?:'Administrator granted temporary billing grace.');$success='Dunning grace updated.';}
    elseif($op==='note'){billing_operations_add_note($pdo,$admin,(string)($_POST['account_id']??''),(string)($_POST['note_type']??'general'),(string)($_POST['body']??''));$success='Billing note added.';}
    elseif($op==='extend_trial'){billing_operations_extend_trial($pdo,$config,$admin,(string)($_POST['account_id']??''),(int)($_POST['days']??7),$reason?:'Administrator extended the Stripe trial.');$success='Stripe trial extended and resynchronized.';}
    elseif($op==='resync'){billing_operations_resync_account($pdo,$config,$admin,(string)($_POST['account_id']??''));billing_operations_snapshot_day($pdo);$success='Account resynchronized from Stripe.';}
    elseif($op==='feedback'){billing_operations_record_cancellation_feedback($pdo,$admin,(string)($_POST['account_id']??''),'admin',(string)($_POST['reason_code']??'other'),(string)($_POST['feedback_text']??''),!empty($_POST['win_back_eligible']));$success='Cancellation feedback recorded.';}
    else throw new RuntimeException('Unknown billing operations action.');
}catch(Throwable $e){$error=$e->getMessage();}}
$settings=billing_operations_settings($pdo);$metrics=billing_operations_current_metrics($pdo);$snapshots=billing_operations_daily_snapshots($pdo,45);$latest=$snapshots[0]??null;$packages=billing_operations_revenue_by_package($pdo);$dunning=billing_operations_dunning_cases($pdo,200);$trials=billing_operations_trial_accounts($pdo);$alerts=billing_operations_alerts($pdo,100);$feedback=billing_operations_feedback($pdo,null,100);$commercial=commercial_promotions_ready($pdo)?commercial_revenue_adjustment_summary($pdo,30):['gross_cents'=>0,'discount_cents'=>0,'net_cents'=>0,'credit_issued_cents'=>0,'debit_issued_cents'=>0];$taxMetrics=commercial_billing_ready($pdo)?commercial_billing_tax_summary($pdo,30):['tax_cents'=>0,'invoice_count'=>0,'automatic_tax_count'=>0,'tax_id_accounts'=>0,'drift_count'=>0];
$money=fn(int $c)=>'$'.number_format($c/100,2);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billing Analytics · Annotated Admin</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><?=admin_ui_sidebar('billing_analytics')?>
